    return sum(1 for word in words if 'G' in word)

def count_words_without_g(words):
    return sum(1 for word in words if 'G' not in word)

def count_words_with_g_in_all_combinations():
    words = [''.join(sorted(pair)) for pair in itertools.combinations(list('ABCDEFGHIJKL'), 2)]
    words.sort()
    return count_words_with_g(words) / len(words)

def count_words_without_g_in_all_combinations():
    words = [''.join(sorted(pair)) for pair in itertools.combinations(list('ABCDEFGHIJKL'), 2)]
    words.sort()
    return count_words_without_g(words) / len(words)

prob_with_g = count_words_with_g_in_all_combinations()
prob_without_g = count_words_without_g_in_all_combinations()

print(prob_with_g, prob_without_g)

