import math

def greedy_algorithm(N):
    coins = [25, 10, 1]
    count = 0
    for coin in coins:
        while N >= coin:
            N -= coin
            count += 1
    return count

def is_greedy_successful(N):
    count = greedy_algorithm(N)
    return count == math.floor(N / 25) + math.floor(N / 10) + math.floor(N / 1)

def find_greedy_successful_values(N_max):
    greedy_successful_values = []
    for N in range(1, N_max + 1):
        if is_greedy_successful(N):
            greedy_successful_values.append(N)
    return greedy_successful_values

greedy_successful_values = find_greedy_successful_values(1000)
print(greedy_successful_values)

